class Solution {
  public int minDifference(int[] nums) {
    int n = nums.length;
    int base = 0, mn = Integer.MAX_VALUE, mx = 0;
    for (int i = 0; i < n; i++) {
      if (nums[i] == -1) {
        if (i > 0 && nums[i - 1] != -1) {
          mn = Math.min(mn, nums[i - 1]);
          mx = Math.max(mx, nums[i - 1]);
        }
        if (i + 1 < n && nums[i + 1] != -1) {
          mn = Math.min(mn, nums[i + 1]);
          mx = Math.max(mx, nums[i + 1]);
        }
      } else if (i > 0 && nums[i - 1] != -1) {
        base = Math.max(base, Math.abs(nums[i] - nums[i - 1]));
      }
    }
    if (mx == 0) return base;
    int lo = base, hi = 1_000_000_000;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (ok(nums, mid, mn, mx)) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  }

  private static boolean ok(int[] nums, int d, int mn, int mx) {
    long x = (long) mn + d, y = (long) mx - d;
    if (y < 1) y = x;
    int n = nums.length;
    for (int i = 0; i < n; ) {
      if (nums[i] != -1) {
        i++;
        continue;
      }
      int j = i;
      while (j < n && nums[j] == -1) j++;
      int len = j - i;
      boolean hasA = i > 0, hasB = j < n;
      long a = hasA ? nums[i - 1] : 0, b = hasB ? nums[j] : 0;
      boolean good;
      if (hasA && hasB) {
        good = both(a, b, x, d) || both(a, b, y, d);
        if (!good && len >= 2 && Math.abs(x - y) <= d) {
          good =
              Math.abs(a - x) <= d && Math.abs(b - y) <= d
                  || Math.abs(a - y) <= d && Math.abs(b - x) <= d;
        }
        if (len == 1) good = both(a, b, x, d) || both(a, b, y, d);
      } else {
        long e = hasA ? a : b;
        good = Math.abs(e - x) <= d || Math.abs(e - y) <= d;
      }
      if (!good) return false;
      i = j;
    }
    return true;
  }

  private static boolean both(long a, long b, long z, int d) {
    return Math.abs(a - z) <= d && Math.abs(b - z) <= d;
  }
}
